(() => {
App.csrfToken = localStorage.getItem(tenantStorageKey('csrf')) || App.csrfToken || '';
const AUTH_REQUIRED_MESSAGE = 'Phiên đăng nhập đã hết hạn, vui lòng đăng nhập lại';
function redirectToLoginOnAuthFailure() {
if (window.__TenantAppSessionExpired) return;
window.__TenantAppSessionExpired = true;
if (typeof clearClientSession === 'function') {
clearClientSession();
} else {
App.token = '';
App.user = null;
App.csrfToken = '';
localStorage.removeItem(tenantStorageKey('token'));
localStorage.removeItem(tenantStorageKey('user'));
localStorage.removeItem(tenantStorageKey('csrf'));
}
if (typeof showLogin === 'function') showLogin();
}
function apiErrorMessage(response, payload) {
const serverMessage = payload?.error?.message || payload?.message || '';
if (serverMessage && serverMessage !== 'Internal Server Error') return serverMessage;
const status = Number(response?.status || 0);
if (status === 400 || status === 422) return 'Du lieu khong hop le. Vui long kiem tra lai thong tin.';
if (status === 401) return AUTH_REQUIRED_MESSAGE;
if (status === 403) return 'Ban khong co quyen thuc hien thao tac nay.';
if (status === 404) return 'Khong tim thay API hoac du lieu can xu ly.';
if (status === 409) return 'Du lieu bi xung dot. Vui long tai lai va thu lai.';
if (status === 419) return 'Phien dang nhap hoac CSRF token khong hop le. Vui long dang nhap lai.';
if (status >= 500) return 'Loi server khi xu ly yeu cau. Vui long kiem tra nhat ky he thong.';
return 'Khong nhan duoc phan hoi hop le tu he thong.';
}
function networkErrorMessage(error) {
if (error instanceof TypeError) return 'Khong the ket noi may chu. Vui long kiem tra mang va thu lai.';
return error?.message || 'Khong nhan duoc phan hoi hop le tu he thong.';
}
window.api = async function secureApi(url, options = {}) {
setLoading(true);
try {
const method = String(options.method || 'GET').toUpperCase();
const headers = { Accept: 'application/json' };
const isFormData = options.body instanceof FormData;
if (options.body && !isFormData) {
headers['Content-Type'] = 'application/json';
}
if (!options.public && !App.token) {
redirectToLoginOnAuthFailure();
throw new Error(AUTH_REQUIRED_MESSAGE);
}
if (!options.public && typeof shouldCallApi === 'function' && !shouldCallApi(url, method)) {
return typeof accessDeniedPayload === 'function' ? accessDeniedPayload(url) : null;
}
if (App.token && !options.public) {
headers.Authorization = `Bearer ${App.token}`;
}
if (!options.public && !['GET', 'HEAD', 'OPTIONS'].includes(method)) {
App.csrfToken = App.csrfToken || localStorage.getItem(tenantStorageKey('csrf')) || '';
if (!App.csrfToken) {
throw new Error('Phiên đăng nhập thiếu CSRF token, vui lòng đăng nhập lại');
}
headers['X-CSRF-Token'] = App.csrfToken;
}
let response;
try {
response = await fetch(url, {
method,
headers,
credentials: 'same-origin',
body: options.body ? (isFormData ? options.body : JSON.stringify(options.body)) : undefined,
});
} catch (error) {
throw new Error(networkErrorMessage(error));
}
const payload = await response.json().catch(() => null);
if (payload?.data?.csrfToken) {
App.csrfToken = payload.data.csrfToken;
localStorage.setItem(tenantStorageKey('csrf'), App.csrfToken);
}
if (response.status === 401 && !options.public && !String(url).includes('/api/auth/logout')) {
redirectToLoginOnAuthFailure();
throw new Error(AUTH_REQUIRED_MESSAGE);
}
if (response.status === 403 && !options.public) {
if (typeof renderAccessDeniedForCurrentScreen === 'function') renderAccessDeniedForCurrentScreen(payload?.error?.message || 'Bạn không có quyền truy cập');
return typeof accessDeniedPayload === 'function' ? accessDeniedPayload(url) : null;
}
if (!response.ok || !payload?.ok) {
throw new Error(apiErrorMessage(response, payload));
}
return payload.data;
} finally {
setLoading(false);
}
};
function clearClientSession() {
App.token = '';
App.user = null;
App.csrfToken = '';
localStorage.removeItem(tenantStorageKey('token'));
localStorage.removeItem(tenantStorageKey('user'));
localStorage.removeItem(tenantStorageKey('csrf'));
}
window.clearClientSession = clearClientSession;
})();
